CREATE TABLE members (id VARCHAR(64) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents (id VARCHAR(128) PRIMARY KEY, owner_id VARCHAR(64) NOT NULL, kind VARCHAR(40) NOT NULL, body TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX documents_owner_kind ON documents(owner_id, kind);
CREATE INDEX documents_kind ON documents(kind);
CREATE TABLE reset_tokens (token_hash VARCHAR(128) PRIMARY KEY, member_id VARCHAR(64) NOT NULL REFERENCES members(id), expires_at TIMESTAMP NOT NULL);
CREATE TABLE daily_usage (member_id VARCHAR(64) NOT NULL, usage_day VARCHAR(10) NOT NULL, kind VARCHAR(20) NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(member_id,usage_day,kind));
